/* Banco de 160 investigaciones. Expedientes 1 a 10 adaptados por curso. */
window.MENTAT_BANK=[{"id":"N5-001","grade":5,"level":1,"skill":"inferencia","title":"Expediente 1: Las semillas del patio","story":"• Dos semillas iguales reciben la misma luz. Solo una recibe agua y solo esa germina.","question":"¿Qué factor cambió?","options":["El agua","La luz","El tipo de semilla"],"correct":0,"explain":"El agua fue la condición diferente.","hint":"Compara lo que recibió cada semilla.","hint2":"Compara las evidencias y evita afirmar más de lo que permiten."},{"id":"N5-002","grade":5,"level":1,"skill":"evaluación de fuentes","title":"Expediente 2: El préstamo registrado","story":"• Un libro fue prestado el lunes. El plazo vence el viernes y hoy es martes.","question":"¿Qué sabemos?","options":["Fue robado","El préstamo sigue vigente","Se perdió"],"correct":1,"explain":"El plazo aún no ha vencido.","hint":"Observa las fechas.","hint2":"Compara las evidencias y evita afirmar más de lo que permiten."},{"id":"N5-003","grade":5,"level":1,"skill":"lógica deductiva","title":"Expediente 3: La sombra del árbol","story":"• A las diez la sombra es larga. A mediodía es más corta. El árbol no se movió.","question":"¿Qué cambió?","options":["El árbol","La posición aparente del Sol","El suelo"],"correct":1,"explain":"La posición aparente del Sol modifica las sombras.","hint":"Piensa en la hora del día.","hint2":"Compara las evidencias y evita afirmar más de lo que permiten."},{"id":"N5-004","grade":5,"level":1,"skill":"contradicciones","title":"Expediente 4: La caja de fichas","story":"• Una caja tiene tres fichas rojas y una azul. Se saca una al azar.","question":"¿Cuál es más probable?","options":["Azul","Igual probabilidad","Roja"],"correct":2,"explain":"Hay tres fichas rojas frente a una azul.","hint":"Cuenta las fichas.","hint2":"Compara las evidencias y evita afirmar más de lo que permiten."},{"id":"N5-005","grade":5,"level":1,"skill":"pensamiento crítico","title":"Expediente 5: La fotografía del patio","story":"• Una foto muestra el patio mojado. Nadie vio llover y hay una manguera junto a la puerta.","question":"¿Qué se puede asegurar?","options":["Llovió toda la noche","El patio estaba mojado","La manguera fue usada"],"correct":1,"explain":"La foto confirma el estado del patio, no su causa.","hint":"Distingue lo visible de lo supuesto.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N5-006","grade":5,"level":1,"skill":"observación","title":"Expediente 6: Las pisadas en arena","story":"• Hay dos tipos de huellas cerca de una caja: unas pequeñas y otras grandes. No sabemos cuándo se formaron.","question":"¿Qué información falta para identificar al último visitante?","options":["El color de la caja","La edad del árbol","El momento de las huellas"],"correct":2,"explain":"Sin tiempo ni testigos no sabemos quién pasó al final.","hint":"Piensa en el orden de los hechos.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N5-007","grade":5,"level":1,"skill":"causa y correlación","title":"Expediente 7: La planta del aula","story":"• Una planta creció cuatro centímetros en dos semanas. También cambiaron el riego y la luz.","question":"¿Qué conclusión es prudente?","options":["No sabemos qué cambio produjo el crecimiento","Solo fue la luz","Solo fue el agua"],"correct":0,"explain":"Dos factores cambiaron al mismo tiempo.","hint":"Cuenta las condiciones que variaron.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N5-008","grade":5,"level":1,"skill":"planificación","title":"Expediente 8: El puente seguro","story":"• Hay dos puentes: el primero es corto pero está dañado; el segundo es más largo y está habilitado.","question":"¿Cuál elegirías?","options":["El primero por rapidez","El segundo por seguridad","Cualquiera sin mirar"],"correct":1,"explain":"La seguridad tiene prioridad frente a ahorrar recorrido.","hint":"Observa el estado de los puentes.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N5-009","grade":5,"level":1,"skill":"metacognición","title":"Expediente 9: El error del aprendiz","story":"• Un aprendiz respondió sin leer la última pista y se equivocó. Luego la leyó y corrigió su conclusión.","question":"¿Qué estrategia mejoró su respuesta?","options":["Adivinar de nuevo","No cambiar nunca","Revisar la evidencia omitida"],"correct":2,"explain":"Volver a las pistas permitió corregir el razonamiento.","hint":"Piensa qué hizo antes de corregir.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N5-010","grade":5,"level":1,"skill":"cálculo aplicado","title":"Expediente 10: Las provisiones","story":"• Hay 18 raciones. Cada equipo necesita 6 y todos deben recibir lo mismo.","question":"¿Cuántos equipos completos pueden abastecerse?","options":["Tres","Cuatro","Dos"],"correct":0,"explain":"18 dividido entre 6 es 3.","hint":"Agrupa las raciones de seis en seis.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N5-011","grade":5,"level":2,"skill":"análisis documental","title":"Expediente 11: La bitácora alterada","story":"Informe para 5.º básico:\n• La bitácora registra una salida a las 08:15.\n• El reloj de la torre se detuvo a las 08:00.\n• El registro fue escrito a mano después del incidente.","question":"¿Qué conviene verificar primero?","options":["La hora usando un reloj independiente","La caligrafía del guardia demuestra culpa","La salida nunca ocurrió"],"correct":0,"explain":"La hora escrita puede ser inexacta si el reloj local estaba detenido.","hint":"Compara el reloj con una fuente independiente.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-012","grade":5,"level":2,"skill":"observación","title":"Expediente 12: La sala silenciosa","story":"Informe para 5.º básico:\n• La puerta está cerrada por dentro.\n• Hay una ventana abierta.\n• El polvo del alféizar presenta una marca reciente.","question":"¿Qué afirmación es prudente?","options":["La ventana pudo haber sido utilizada","La persona salió necesariamente por la ventana","La habitación estuvo siempre vacía"],"correct":0,"explain":"La marca sugiere actividad, pero no determina quién ni cómo.","hint":"No confundas indicio con certeza.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-013","grade":5,"level":2,"skill":"pensamiento espacial","title":"Expediente 13: El mapa incompleto","story":"Informe para 5.º básico:\n• El mapa marca un puente al norte.\n• El informe de terreno indica que ese puente está cortado.\n• Existe un sendero alternativo sin inspeccionar.","question":"¿Cuál es la mejor decisión?","options":["Usar el puente porque figura en el mapa","Inspeccionar el sendero antes de elegir ruta","Afirmar que no hay caminos"],"correct":1,"explain":"Un mapa desactualizado no reemplaza la verificación del terreno.","hint":"Contrasta mapa e informe reciente.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-014","grade":5,"level":2,"skill":"probabilidad","title":"Expediente 14: La predicción del oráculo","story":"Informe para 5.º básico:\n• Un pronóstico anticipó lluvia en siete de diez días similares.\n• Hoy presenta condiciones semejantes.\n• El pronóstico no garantiza el resultado.","question":"¿Cómo interpretar el pronóstico?","options":["Lloverá con absoluta seguridad","Es imposible que llueva","La lluvia es probable, pero no segura"],"correct":2,"explain":"Una frecuencia alta no equivale a certeza.","hint":"Distingue probabilidad de seguridad.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-015","grade":5,"level":2,"skill":"comprensión","title":"Expediente 15: La orden ambigua","story":"Informe para 5.º básico:\n• El mensaje dice: «Entregar antes del tercer turno».\n• No especifica si el tercer turno está incluido.\n• El responsable no está disponible por el momento.","question":"¿Qué interpretación es más responsable?","options":["Aclarar el plazo antes de comprometer la entrega","Suponer que cualquier hora sirve","Cambiar el mensaje original"],"correct":0,"explain":"Una instrucción ambigua exige aclaración, no una suposición oculta.","hint":"Localiza la parte que admite dos interpretaciones.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-016","grade":5,"level":2,"skill":"método científico","title":"Expediente 16: El experimento de las semillas","story":"Informe para 5.º básico:\n• Dos plantas recibieron distinta cantidad de agua.\n• También crecieron con distinta luz.\n• La planta más iluminada creció más.","question":"¿Qué impide atribuir la diferencia solo al agua?","options":["Las dos variables cambiaron","Las plantas tienen hojas","La luz no puede influir"],"correct":0,"explain":"Al variar luz y agua no se aísla una sola causa.","hint":"Identifica todas las condiciones que cambiaron.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-017","grade":5,"level":2,"skill":"evaluación de testimonios","title":"Expediente 17: El testigo distante","story":"Informe para 5.º básico:\n• Una persona oyó un golpe desde otro edificio.\n• No vio el lugar de origen.\n• Otro testigo observó una puerta cerrarse al mismo tiempo.","question":"¿Qué sabemos con mayor seguridad?","options":["Que alguien cometió un delito","Que hubo sonidos y una puerta cerrándose","Que ambos testigos vieron lo mismo"],"correct":1,"explain":"Los testimonios describen observaciones distintas, no una causa confirmada.","hint":"Separa lo oído de lo observado.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-018","grade":5,"level":2,"skill":"patrones no numéricos","title":"Expediente 18: Las tres señales","story":"Informe para 5.º básico:\n• Cada aviso de emergencia comienza con círculo rojo.\n• Dos mensajes auténticos muestran círculo rojo y sello azul.\n• Un tercer mensaje tiene círculo verde y no incluye sello.","question":"¿Qué procede hacer?","options":["Tratar el tercer mensaje como no verificado","Declarar que el tercero es auténtico","Ignorar todos los mensajes"],"correct":0,"explain":"La falta de rasgos de autenticidad exige comprobación.","hint":"Compara señales comunes de los avisos verificados.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-019","grade":5,"level":2,"skill":"ética y decisión","title":"Expediente 19: El recurso compartido","story":"Informe para 5.º básico:\n• Hay un equipo médico para dos grupos.\n• El grupo A presenta una urgencia documentada.\n• El grupo B tiene una necesidad menor que puede esperar.","question":"¿Qué criterio es más defendible?","options":["Atender primero la urgencia documentada","Favorecer al grupo más numeroso sin evaluar gravedad","Decidir por amistad"],"correct":0,"explain":"La prioridad se fundamenta en necesidad y gravedad, no favoritismo.","hint":"Diferencia urgencia de preferencia.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-020","grade":5,"level":2,"skill":"contexto histórico","title":"Expediente 20: La carta sin fecha","story":"Informe para 5.º básico:\n• Una carta menciona una sequía.\n• No tiene fecha ni autor identificado.\n• Un registro regional confirma sequías en varios años distintos.","question":"¿Qué dato falta para situarla históricamente?","options":["El color de la tinta","Una fecha o referencia temporal verificable","El número de palabras"],"correct":1,"explain":"Sin referencia temporal no se puede asociar con seguridad a un año.","hint":"Busca qué permite ubicar un documento en el tiempo.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-021","grade":5,"level":3,"skill":"fiabilidad","title":"Expediente 21: El sensor defectuoso","story":"Informe para 5.º básico:\n• Dos sensores marcan 18 grados.\n• Un tercero indica 45 grados.\n• El tercer sensor no ha sido calibrado recientemente.","question":"¿Qué acción mejora la fiabilidad?","options":["Usar únicamente la lectura extrema","Revisar la calibración y contrastar mediciones","Promediar sin examinar errores"],"correct":1,"explain":"Una lectura atípica exige comprobar el instrumento.","hint":"¿Qué diferencia hay entre los sensores?","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-022","grade":5,"level":3,"skill":"deducción","title":"Expediente 22: El idioma desconocido","story":"Informe para 5.º básico:\n• La palabra «tal» aparece en todos los saludos.\n• Nunca aparece en mensajes de despedida del archivo.\n• El corpus contiene solo seis mensajes.","question":"¿Qué hipótesis es razonable?","options":["«tal» podría relacionarse con saludar","«tal» significa necesariamente emperador","Ya conocemos todo el idioma"],"correct":0,"explain":"La coincidencia sugiere una función, pero la muestra es pequeña.","hint":"Observa el contexto de aparición de la palabra.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-023","grade":5,"level":3,"skill":"alfabetización mediática","title":"Expediente 23: El retrato recortado","story":"Informe para 5.º básico:\n• Una imagen muestra a un guardia corriendo.\n• La fotografía completa revela que corre hacia una persona caída.\n• El titular recortado dice: «Guardia huye».","question":"¿Qué demuestra el caso?","options":["Que el recorte puede alterar la interpretación","Que todas las fotos son falsas","Que el guardia cometió una falta"],"correct":0,"explain":"Omitir contexto visual puede cambiar el significado atribuido.","hint":"Compara el recorte con la imagen completa.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-024","grade":5,"level":3,"skill":"planificación","title":"Expediente 24: La ruta de los mensajeros","story":"Informe para 5.º básico:\n• Ruta A es corta, pero atraviesa una zona cerrada.\n• Ruta B es más larga y está confirmada como transitable.\n• El mensaje debe llegar sin poner en riesgo al equipo.","question":"¿Qué ruta conviene elegir?","options":["Ruta A por ser más corta","Ruta B por ser transitable","Ninguna porque ambas tienen distancia"],"correct":1,"explain":"La seguridad y viabilidad importan más que la distancia mínima.","hint":"Una ruta corta no sirve si está cerrada.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-025","grade":5,"level":3,"skill":"organización de datos","title":"Expediente 25: La lista duplicada","story":"Informe para 5.º básico:\n• El archivo contiene 12 nombres.\n• Dos nombres están repetidos exactamente.\n• El Consejo solicita contar personas distintas.","question":"¿Qué se debe hacer?","options":["Contar 12 personas sin revisar","Eliminar todos los nombres","Revisar duplicados antes de contar"],"correct":2,"explain":"Los registros duplicados pueden inflar el total de personas.","hint":"Distingue registros de individuos.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-026","grade":5,"level":3,"skill":"sesgos","title":"Expediente 26: La profecía flexible","story":"Informe para 5.º básico:\n• Un consejero anunció: «Habrá un cambio importante».\n• Después de cualquier suceso, afirma que lo predijo.\n• Nunca indicó fecha ni criterio para verificarlo.","question":"¿Qué problema tiene la afirmación?","options":["No permite una comprobación clara","Es una predicción numérica exacta","Queda demostrada por repetirse"],"correct":0,"explain":"Una predicción demasiado vaga puede acomodarse a casi cualquier resultado.","hint":"Pregunta cómo podría demostrarse que estaba equivocada.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-027","grade":5,"level":3,"skill":"estadística crítica","title":"Expediente 27: La muestra parcial","story":"Informe para 5.º básico:\n• Se entrevistó a diez personas de una sola sala.\n• Nueve apoyan una medida.\n• La ciudad tiene miles de habitantes.","question":"¿Qué conclusión es válida?","options":["Toda la ciudad apoya la medida","Nueve de las diez personas entrevistadas la apoyan","Nadie se opone"],"correct":1,"explain":"Una muestra limitada no representa automáticamente a toda la población.","hint":"Distingue la muestra de la población.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-028","grade":5,"level":3,"skill":"memoria de trabajo","title":"Expediente 28: El archivo de sonidos","story":"Informe para 5.º básico:\n• Secuencia registrada: campana, tambor, flauta, campana.\n• La tercera señal fue flauta.\n• El técnico debe reconstruir el orden.","question":"¿Qué instrumento sonó inmediatamente antes de la última campana?","options":["Tambor","Flauta","Campana"],"correct":1,"explain":"La tercera señal fue flauta y la cuarta, campana.","hint":"Enumera las señales en orden.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-029","grade":5,"level":3,"skill":"negociación","title":"Expediente 29: El pacto entre casas","story":"Informe para 5.º básico:\n• Dos casas necesitan agua.\n• La primera controla el depósito.\n• La segunda dispone de filtros necesarios para potabilizarla.","question":"¿Qué acuerdo atiende mejor los intereses de ambas?","options":["Compartir agua tratada mediante cooperación","Destruir los filtros","Negarse a conversar"],"correct":0,"explain":"Identificar necesidades complementarias facilita una solución cooperativa.","hint":"¿Qué aporta cada casa que necesita la otra?","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-030","grade":5,"level":3,"skill":"clasificación","title":"Expediente 30: La puerta de tres símbolos","story":"Informe para 5.º básico:\n• Las puertas seguras muestran estrella y triángulo.\n• Una puerta tiene estrella y triángulo.\n• Otra solo muestra estrella.","question":"¿Cuál cumple los dos criterios observados?","options":["Solo la primera puerta","Solo la segunda puerta","Ambas"],"correct":0,"explain":"La regla exige ambos símbolos, no solo uno.","hint":"Comprueba cada condición por separado.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-031","grade":5,"level":4,"skill":"historia y fuentes","title":"Expediente 31: La crónica contradictoria","story":"Informe para 5.º básico:\n• Una crónica oficial atribuye una victoria a un solo comandante.\n• Cartas de participantes describen acciones de varios grupos.\n• Los documentos fueron escritos desde perspectivas diferentes.","question":"¿Qué método ayuda a comprender el hecho?","options":["Comparar testimonios y sus perspectivas","Aceptar solo la versión oficial","Descartar todas las fuentes"],"correct":0,"explain":"Contrastar perspectivas reduce el riesgo de una interpretación unilateral.","hint":"Ninguna fuente se interpreta sin contexto.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-032","grade":5,"level":4,"skill":"causalidad","title":"Expediente 32: La alarma y el humo","story":"Informe para 5.º básico:\n• Se activó una alarma.\n• Poco después se observó humo.\n• No se ha identificado el origen del humo.","question":"¿Qué conclusión evita un error causal?","options":["La alarma produjo el humo","La alarma y el humo ocurrieron próximos, pero falta investigar su relación","El humo nunca existió"],"correct":1,"explain":"La sucesión temporal no prueba causalidad.","hint":"Ocurrir antes no siempre significa causar.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-033","grade":5,"level":4,"skill":"lenguaje","title":"Expediente 33: La traducción dudosa","story":"Informe para 5.º básico:\n• Un término antiguo puede significar «casa» o «familia».\n• La frase habla de proteger a sus integrantes.\n• No existe una traducción confirmada.","question":"¿Qué conviene hacer?","options":["Reconocer las dos posibilidades y buscar contexto","Elegir una traducción al azar como definitiva","Eliminar el término"],"correct":0,"explain":"La ambigüedad se resuelve con contexto y evidencia lingüística.","hint":"Busca pistas en las palabras cercanas.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-034","grade":5,"level":4,"skill":"observación científica","title":"Expediente 34: La sombra del reloj","story":"Informe para 5.º básico:\n• La sombra era larga temprano.\n• Al mediodía fue más corta.\n• La medición se hizo en el mismo lugar.","question":"¿Qué variable se relaciona con el cambio?","options":["La posición aparente del Sol","El nombre del observador","La tinta del registro"],"correct":0,"explain":"La longitud de la sombra depende del ángulo de iluminación.","hint":"Piensa qué cambia en el cielo durante el día.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-035","grade":5,"level":4,"skill":"lógica","title":"Expediente 35: El permiso perdido","story":"Informe para 5.º básico:\n• Toda persona autorizada tiene credencial vigente.\n• Una persona no tiene credencial vigente.\n• No hay excepciones registradas a la regla.","question":"¿Qué se deduce bajo esa regla?","options":["Esa persona no está autorizada","La persona tiene dos credenciales","La regla no se aplica"],"correct":0,"explain":"Si la credencial vigente es condición necesaria, su ausencia excluye autorización.","hint":"Una condición necesaria debe cumplirse.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-036","grade":5,"level":4,"skill":"verificación","title":"Expediente 36: El rumor del mercado","story":"Informe para 5.º básico:\n• Tres personas repiten la misma noticia.\n• Las tres la escucharon de un único mensaje anónimo.\n• No hay confirmación externa.","question":"¿Cuántas fuentes independientes hay?","options":["Tres","Una fuente original no verificada","Cuatro"],"correct":1,"explain":"Repetir una noticia no crea nuevas fuentes independientes.","hint":"Rastrea el origen de cada repetición.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-037","grade":5,"level":4,"skill":"razonamiento ético","title":"Expediente 37: La elección del Consejo","story":"Informe para 5.º básico:\n• Una norma se aplicó a un estudiante.\n• Otro estudiante en la misma situación recibió una excepción sin justificación.\n• El Consejo revisa la coherencia de sus decisiones.","question":"¿Qué principio debe examinarse?","options":["Aplicación equitativa de las normas","Preferencia personal del consejero","Cantidad de aplausos"],"correct":0,"explain":"Las decisiones equivalentes requieren criterios consistentes o razones explícitas.","hint":"Compara situaciones y justificaciones.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-038","grade":5,"level":4,"skill":"hipótesis científica","title":"Expediente 38: El mineral brillante","story":"Informe para 5.º básico:\n• Dos minerales tienen el mismo color.\n• Uno responde a un imán y el otro no.\n• Se desconoce su composición.","question":"¿Qué afirmación es correcta?","options":["Son necesariamente idénticos","El color por sí solo no determina que sean el mismo mineral","Ambos son magnéticos"],"correct":1,"explain":"Una propiedad compartida no basta para identificar materiales.","hint":"Busca una característica que los diferencie.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-039","grade":5,"level":4,"skill":"secuenciación","title":"Expediente 39: La contraseña fragmentada","story":"Informe para 5.º básico:\n• Primera instrucción: activar el panel.\n• Segunda: introducir la clave.\n• Tercera: confirmar el acceso.","question":"¿Qué debe hacerse inmediatamente después de activar el panel?","options":["Confirmar acceso","Introducir la clave","Cerrar el panel"],"correct":1,"explain":"La segunda acción sigue a la primera.","hint":"Revisa el orden explícito de las instrucciones.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N5-040","grade":5,"level":4,"skill":"investigación","title":"Expediente 40: La biblioteca extraviada","story":"Informe para 5.º básico:\n• El inventario indica que faltan tres libros.\n• Dos aparecen prestados con fecha de devolución futura.\n• Del tercero no existe registro de préstamo.","question":"¿Qué caso requiere investigación adicional?","options":["Los tres por igual","Solo los dos prestados","El libro sin registro de préstamo"],"correct":2,"explain":"Los préstamos documentados explican dos ausencias; la tercera sigue sin explicación.","hint":"Separa ausencias justificadas de las no justificadas.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-001","grade":6,"level":1,"skill":"evaluación de fuentes","title":"Expediente 1: La encuesta del recreo","story":"• Cinco amigos opinan igual sobre el menú, pero el curso tiene treinta estudiantes.","question":"¿Cuál es la limitación?","options":["Muestra poco representativa","Todos piensan igual","La encuesta es definitiva"],"correct":0,"explain":"El grupo de amigos puede no representar al curso.","hint":"¿Quiénes quedaron fuera?","hint2":"Compara las evidencias y evita afirmar más de lo que permiten."},{"id":"N6-002","grade":6,"level":1,"skill":"lógica deductiva","title":"Expediente 2: El discurso original","story":"• Un texto escolar resume un discurso histórico y el archivo conserva el documento original.","question":"¿Qué permite verificar las palabras exactas?","options":["El resumen","El documento original","Un comentario"],"correct":1,"explain":"El original es la fuente primaria de esas palabras.","hint":"Busca la fuente directa.","hint2":"Compara las evidencias y evita afirmar más de lo que permiten."},{"id":"N6-003","grade":6,"level":1,"skill":"contradicciones","title":"Expediente 3: Dos recipientes","story":"• Dos recipientes tienen igual agua. Uno se deja al sol y otro a la sombra.","question":"¿Qué se compara?","options":["La cantidad de agua","El recipiente","La exposición solar"],"correct":2,"explain":"La exposición solar es la condición diferente.","hint":"Identifica la variable.","hint2":"Compara las evidencias y evita afirmar más de lo que permiten."},{"id":"N6-004","grade":6,"level":1,"skill":"pensamiento crítico","title":"Expediente 4: La señal interrumpida","story":"• Se enviaron mensajes 1, 2 y 3. Solo llegaron 1 y 3.","question":"¿Qué sabemos?","options":["No llegó el mensaje 2","El mensaje 2 nunca existió","Alguien lo escondió"],"correct":0,"explain":"La recepción incompleta no demuestra la causa.","hint":"Distingue el hecho de la explicación.","hint2":"Compara las evidencias y evita afirmar más de lo que permiten."},{"id":"N6-005","grade":6,"level":1,"skill":"observación","title":"Expediente 5: El aviso reenviado","story":"• Un aviso sobre suspensión de clases circula en tres chats, pero todos comparten la misma captura sin fecha.","question":"¿Qué paso falta?","options":["Contar los reenvíos","Confirmar fecha y emisor oficial","Dar por cierto el aviso"],"correct":1,"explain":"Los reenvíos no confirman autenticidad ni actualidad.","hint":"Examina el origen y la fecha.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N6-006","grade":6,"level":1,"skill":"causa y correlación","title":"Expediente 6: La marca en el suelo","story":"• Una marca aparece frente a la bodega. Dos personas estuvieron allí, pero no se conoce cuándo surgió.","question":"¿Qué dato ayudaría a atribuirla?","options":["La hora en que apareció","El tamaño de la bodega","El clima de otro año"],"correct":0,"explain":"La secuencia temporal permite evaluar quién pudo producirla.","hint":"Busca una referencia de tiempo.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N6-007","grade":6,"level":1,"skill":"planificación","title":"Expediente 7: La asistencia escolar","story":"• La asistencia subió tras instalar calefacción, pero también se modificó el transporte escolar.","question":"¿Qué se puede concluir?","options":["La calefacción causó todo","El transporte no influyó","No es posible aislar una causa"],"correct":2,"explain":"Dos cambios simultáneos impiden atribuir el efecto a uno solo.","hint":"Identifica ambas intervenciones.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N6-008","grade":6,"level":1,"skill":"metacognición","title":"Expediente 8: El reparto de agua","story":"• Dos comunidades necesitan agua. Una tiene mayor población y la otra enfrenta una sequía más intensa.","question":"¿Qué criterio conviene usar?","options":["Atender solo a la más grande","Evaluar necesidades y urgencia","Elegir al azar"],"correct":1,"explain":"La distribución responsable considera necesidad y riesgo.","hint":"Considera los dos factores.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N6-009","grade":6,"level":1,"skill":"cálculo aplicado","title":"Expediente 9: El registro corregido","story":"• Un equipo descubre que sumó mal las provisiones y vuelve a calcular antes de decidir.","question":"¿Qué habilidad demuestra?","options":["Verificación y autocorrección","Obstinación","Ocultamiento"],"correct":0,"explain":"Comprobar los cálculos evita decisiones basadas en errores.","hint":"Piensa en revisar los procedimientos.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N6-010","grade":6,"level":1,"skill":"inferencia","title":"Expediente 10: Los mapas del almacén","story":"• Se necesitan 24 mapas. Cada paquete contiene 8.","question":"¿Cuántos paquetes completos se necesitan?","options":["Dos","Cuatro","Tres"],"correct":2,"explain":"24 dividido por 8 es 3.","hint":"Divide la cantidad total por paquete.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N6-011","grade":6,"level":2,"skill":"patrones no numéricos","title":"Expediente 11: Las tres señales","story":"Informe para 6.º básico:\n• Cada aviso de emergencia comienza con círculo rojo.\n• Dos mensajes auténticos muestran círculo rojo y sello azul.\n• Un tercer mensaje tiene círculo verde y no incluye sello.","question":"¿Qué procede hacer?","options":["Tratar el tercer mensaje como no verificado","Declarar que el tercero es auténtico","Ignorar todos los mensajes"],"correct":0,"explain":"La falta de rasgos de autenticidad exige comprobación.","hint":"Compara señales comunes de los avisos verificados.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-012","grade":6,"level":2,"skill":"ética y decisión","title":"Expediente 12: El recurso compartido","story":"Informe para 6.º básico:\n• Hay un equipo médico para dos grupos.\n• El grupo A presenta una urgencia documentada.\n• El grupo B tiene una necesidad menor que puede esperar.","question":"¿Qué criterio es más defendible?","options":["Atender primero la urgencia documentada","Favorecer al grupo más numeroso sin evaluar gravedad","Decidir por amistad"],"correct":0,"explain":"La prioridad se fundamenta en necesidad y gravedad, no favoritismo.","hint":"Diferencia urgencia de preferencia.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-013","grade":6,"level":2,"skill":"contexto histórico","title":"Expediente 13: La carta sin fecha","story":"Informe para 6.º básico:\n• Una carta menciona una sequía.\n• No tiene fecha ni autor identificado.\n• Un registro regional confirma sequías en varios años distintos.","question":"¿Qué dato falta para situarla históricamente?","options":["El color de la tinta","Una fecha o referencia temporal verificable","El número de palabras"],"correct":1,"explain":"Sin referencia temporal no se puede asociar con seguridad a un año.","hint":"Busca qué permite ubicar un documento en el tiempo.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-014","grade":6,"level":2,"skill":"fiabilidad","title":"Expediente 14: El sensor defectuoso","story":"Informe para 6.º básico:\n• Dos sensores marcan 18 grados.\n• Un tercero indica 45 grados.\n• El tercer sensor no ha sido calibrado recientemente.","question":"¿Qué acción mejora la fiabilidad?","options":["Usar únicamente la lectura extrema","Revisar la calibración y contrastar mediciones","Promediar sin examinar errores"],"correct":1,"explain":"Una lectura atípica exige comprobar el instrumento.","hint":"¿Qué diferencia hay entre los sensores?","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-015","grade":6,"level":2,"skill":"deducción","title":"Expediente 15: El idioma desconocido","story":"Informe para 6.º básico:\n• La palabra «tal» aparece en todos los saludos.\n• Nunca aparece en mensajes de despedida del archivo.\n• El corpus contiene solo seis mensajes.","question":"¿Qué hipótesis es razonable?","options":["«tal» podría relacionarse con saludar","«tal» significa necesariamente emperador","Ya conocemos todo el idioma"],"correct":0,"explain":"La coincidencia sugiere una función, pero la muestra es pequeña.","hint":"Observa el contexto de aparición de la palabra.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-016","grade":6,"level":2,"skill":"alfabetización mediática","title":"Expediente 16: El retrato recortado","story":"Informe para 6.º básico:\n• Una imagen muestra a un guardia corriendo.\n• La fotografía completa revela que corre hacia una persona caída.\n• El titular recortado dice: «Guardia huye».","question":"¿Qué demuestra el caso?","options":["Que el recorte puede alterar la interpretación","Que todas las fotos son falsas","Que el guardia cometió una falta"],"correct":0,"explain":"Omitir contexto visual puede cambiar el significado atribuido.","hint":"Compara el recorte con la imagen completa.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-017","grade":6,"level":2,"skill":"planificación","title":"Expediente 17: La ruta de los mensajeros","story":"Informe para 6.º básico:\n• Ruta A es corta, pero atraviesa una zona cerrada.\n• Ruta B es más larga y está confirmada como transitable.\n• El mensaje debe llegar sin poner en riesgo al equipo.","question":"¿Qué ruta conviene elegir?","options":["Ruta A por ser más corta","Ruta B por ser transitable","Ninguna porque ambas tienen distancia"],"correct":1,"explain":"La seguridad y viabilidad importan más que la distancia mínima.","hint":"Una ruta corta no sirve si está cerrada.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-018","grade":6,"level":2,"skill":"organización de datos","title":"Expediente 18: La lista duplicada","story":"Informe para 6.º básico:\n• El archivo contiene 12 nombres.\n• Dos nombres están repetidos exactamente.\n• El Consejo solicita contar personas distintas.","question":"¿Qué se debe hacer?","options":["Contar 12 personas sin revisar","Eliminar todos los nombres","Revisar duplicados antes de contar"],"correct":2,"explain":"Los registros duplicados pueden inflar el total de personas.","hint":"Distingue registros de individuos.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-019","grade":6,"level":2,"skill":"sesgos","title":"Expediente 19: La profecía flexible","story":"Informe para 6.º básico:\n• Un consejero anunció: «Habrá un cambio importante».\n• Después de cualquier suceso, afirma que lo predijo.\n• Nunca indicó fecha ni criterio para verificarlo.","question":"¿Qué problema tiene la afirmación?","options":["No permite una comprobación clara","Es una predicción numérica exacta","Queda demostrada por repetirse"],"correct":0,"explain":"Una predicción demasiado vaga puede acomodarse a casi cualquier resultado.","hint":"Pregunta cómo podría demostrarse que estaba equivocada.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-020","grade":6,"level":2,"skill":"estadística crítica","title":"Expediente 20: La muestra parcial","story":"Informe para 6.º básico:\n• Se entrevistó a diez personas de una sola sala.\n• Nueve apoyan una medida.\n• La ciudad tiene miles de habitantes.","question":"¿Qué conclusión es válida?","options":["Toda la ciudad apoya la medida","Nueve de las diez personas entrevistadas la apoyan","Nadie se opone"],"correct":1,"explain":"Una muestra limitada no representa automáticamente a toda la población.","hint":"Distingue la muestra de la población.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-021","grade":6,"level":3,"skill":"memoria de trabajo","title":"Expediente 21: El archivo de sonidos","story":"Informe para 6.º básico:\n• Secuencia registrada: campana, tambor, flauta, campana.\n• La tercera señal fue flauta.\n• El técnico debe reconstruir el orden.","question":"¿Qué instrumento sonó inmediatamente antes de la última campana?","options":["Tambor","Flauta","Campana"],"correct":1,"explain":"La tercera señal fue flauta y la cuarta, campana.","hint":"Enumera las señales en orden.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-022","grade":6,"level":3,"skill":"negociación","title":"Expediente 22: El pacto entre casas","story":"Informe para 6.º básico:\n• Dos casas necesitan agua.\n• La primera controla el depósito.\n• La segunda dispone de filtros necesarios para potabilizarla.","question":"¿Qué acuerdo atiende mejor los intereses de ambas?","options":["Compartir agua tratada mediante cooperación","Destruir los filtros","Negarse a conversar"],"correct":0,"explain":"Identificar necesidades complementarias facilita una solución cooperativa.","hint":"¿Qué aporta cada casa que necesita la otra?","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-023","grade":6,"level":3,"skill":"clasificación","title":"Expediente 23: La puerta de tres símbolos","story":"Informe para 6.º básico:\n• Las puertas seguras muestran estrella y triángulo.\n• Una puerta tiene estrella y triángulo.\n• Otra solo muestra estrella.","question":"¿Cuál cumple los dos criterios observados?","options":["Solo la primera puerta","Solo la segunda puerta","Ambas"],"correct":0,"explain":"La regla exige ambos símbolos, no solo uno.","hint":"Comprueba cada condición por separado.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-024","grade":6,"level":3,"skill":"historia y fuentes","title":"Expediente 24: La crónica contradictoria","story":"Informe para 6.º básico:\n• Una crónica oficial atribuye una victoria a un solo comandante.\n• Cartas de participantes describen acciones de varios grupos.\n• Los documentos fueron escritos desde perspectivas diferentes.","question":"¿Qué método ayuda a comprender el hecho?","options":["Comparar testimonios y sus perspectivas","Aceptar solo la versión oficial","Descartar todas las fuentes"],"correct":0,"explain":"Contrastar perspectivas reduce el riesgo de una interpretación unilateral.","hint":"Ninguna fuente se interpreta sin contexto.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-025","grade":6,"level":3,"skill":"causalidad","title":"Expediente 25: La alarma y el humo","story":"Informe para 6.º básico:\n• Se activó una alarma.\n• Poco después se observó humo.\n• No se ha identificado el origen del humo.","question":"¿Qué conclusión evita un error causal?","options":["La alarma produjo el humo","La alarma y el humo ocurrieron próximos, pero falta investigar su relación","El humo nunca existió"],"correct":1,"explain":"La sucesión temporal no prueba causalidad.","hint":"Ocurrir antes no siempre significa causar.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-026","grade":6,"level":3,"skill":"lenguaje","title":"Expediente 26: La traducción dudosa","story":"Informe para 6.º básico:\n• Un término antiguo puede significar «casa» o «familia».\n• La frase habla de proteger a sus integrantes.\n• No existe una traducción confirmada.","question":"¿Qué conviene hacer?","options":["Reconocer las dos posibilidades y buscar contexto","Elegir una traducción al azar como definitiva","Eliminar el término"],"correct":0,"explain":"La ambigüedad se resuelve con contexto y evidencia lingüística.","hint":"Busca pistas en las palabras cercanas.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-027","grade":6,"level":3,"skill":"observación científica","title":"Expediente 27: La sombra del reloj","story":"Informe para 6.º básico:\n• La sombra era larga temprano.\n• Al mediodía fue más corta.\n• La medición se hizo en el mismo lugar.","question":"¿Qué variable se relaciona con el cambio?","options":["La posición aparente del Sol","El nombre del observador","La tinta del registro"],"correct":0,"explain":"La longitud de la sombra depende del ángulo de iluminación.","hint":"Piensa qué cambia en el cielo durante el día.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-028","grade":6,"level":3,"skill":"lógica","title":"Expediente 28: El permiso perdido","story":"Informe para 6.º básico:\n• Toda persona autorizada tiene credencial vigente.\n• Una persona no tiene credencial vigente.\n• No hay excepciones registradas a la regla.","question":"¿Qué se deduce bajo esa regla?","options":["Esa persona no está autorizada","La persona tiene dos credenciales","La regla no se aplica"],"correct":0,"explain":"Si la credencial vigente es condición necesaria, su ausencia excluye autorización.","hint":"Una condición necesaria debe cumplirse.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-029","grade":6,"level":3,"skill":"verificación","title":"Expediente 29: El rumor del mercado","story":"Informe para 6.º básico:\n• Tres personas repiten la misma noticia.\n• Las tres la escucharon de un único mensaje anónimo.\n• No hay confirmación externa.","question":"¿Cuántas fuentes independientes hay?","options":["Tres","Una fuente original no verificada","Cuatro"],"correct":1,"explain":"Repetir una noticia no crea nuevas fuentes independientes.","hint":"Rastrea el origen de cada repetición.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-030","grade":6,"level":3,"skill":"razonamiento ético","title":"Expediente 30: La elección del Consejo","story":"Informe para 6.º básico:\n• Una norma se aplicó a un estudiante.\n• Otro estudiante en la misma situación recibió una excepción sin justificación.\n• El Consejo revisa la coherencia de sus decisiones.","question":"¿Qué principio debe examinarse?","options":["Aplicación equitativa de las normas","Preferencia personal del consejero","Cantidad de aplausos"],"correct":0,"explain":"Las decisiones equivalentes requieren criterios consistentes o razones explícitas.","hint":"Compara situaciones y justificaciones.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-031","grade":6,"level":4,"skill":"hipótesis científica","title":"Expediente 31: El mineral brillante","story":"Informe para 6.º básico:\n• Dos minerales tienen el mismo color.\n• Uno responde a un imán y el otro no.\n• Se desconoce su composición.","question":"¿Qué afirmación es correcta?","options":["Son necesariamente idénticos","El color por sí solo no determina que sean el mismo mineral","Ambos son magnéticos"],"correct":1,"explain":"Una propiedad compartida no basta para identificar materiales.","hint":"Busca una característica que los diferencie.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-032","grade":6,"level":4,"skill":"secuenciación","title":"Expediente 32: La contraseña fragmentada","story":"Informe para 6.º básico:\n• Primera instrucción: activar el panel.\n• Segunda: introducir la clave.\n• Tercera: confirmar el acceso.","question":"¿Qué debe hacerse inmediatamente después de activar el panel?","options":["Confirmar acceso","Introducir la clave","Cerrar el panel"],"correct":1,"explain":"La segunda acción sigue a la primera.","hint":"Revisa el orden explícito de las instrucciones.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-033","grade":6,"level":4,"skill":"investigación","title":"Expediente 33: La biblioteca extraviada","story":"Informe para 6.º básico:\n• El inventario indica que faltan tres libros.\n• Dos aparecen prestados con fecha de devolución futura.\n• Del tercero no existe registro de préstamo.","question":"¿Qué caso requiere investigación adicional?","options":["Los tres por igual","Solo los dos prestados","El libro sin registro de préstamo"],"correct":2,"explain":"Los préstamos documentados explican dos ausencias; la tercera sigue sin explicación.","hint":"Separa ausencias justificadas de las no justificadas.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-034","grade":6,"level":4,"skill":"análisis documental","title":"Expediente 34: La bitácora alterada","story":"Informe para 6.º básico:\n• La bitácora registra una salida a las 08:15.\n• El reloj de la torre se detuvo a las 08:00.\n• El registro fue escrito a mano después del incidente.","question":"¿Qué conviene verificar primero?","options":["La hora usando un reloj independiente","La caligrafía del guardia demuestra culpa","La salida nunca ocurrió"],"correct":0,"explain":"La hora escrita puede ser inexacta si el reloj local estaba detenido.","hint":"Compara el reloj con una fuente independiente.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-035","grade":6,"level":4,"skill":"observación","title":"Expediente 35: La sala silenciosa","story":"Informe para 6.º básico:\n• La puerta está cerrada por dentro.\n• Hay una ventana abierta.\n• El polvo del alféizar presenta una marca reciente.","question":"¿Qué afirmación es prudente?","options":["La ventana pudo haber sido utilizada","La persona salió necesariamente por la ventana","La habitación estuvo siempre vacía"],"correct":0,"explain":"La marca sugiere actividad, pero no determina quién ni cómo.","hint":"No confundas indicio con certeza.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-036","grade":6,"level":4,"skill":"pensamiento espacial","title":"Expediente 36: El mapa incompleto","story":"Informe para 6.º básico:\n• El mapa marca un puente al norte.\n• El informe de terreno indica que ese puente está cortado.\n• Existe un sendero alternativo sin inspeccionar.","question":"¿Cuál es la mejor decisión?","options":["Usar el puente porque figura en el mapa","Inspeccionar el sendero antes de elegir ruta","Afirmar que no hay caminos"],"correct":1,"explain":"Un mapa desactualizado no reemplaza la verificación del terreno.","hint":"Contrasta mapa e informe reciente.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-037","grade":6,"level":4,"skill":"probabilidad","title":"Expediente 37: La predicción del oráculo","story":"Informe para 6.º básico:\n• Un pronóstico anticipó lluvia en siete de diez días similares.\n• Hoy presenta condiciones semejantes.\n• El pronóstico no garantiza el resultado.","question":"¿Cómo interpretar el pronóstico?","options":["Lloverá con absoluta seguridad","Es imposible que llueva","La lluvia es probable, pero no segura"],"correct":2,"explain":"Una frecuencia alta no equivale a certeza.","hint":"Distingue probabilidad de seguridad.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-038","grade":6,"level":4,"skill":"comprensión","title":"Expediente 38: La orden ambigua","story":"Informe para 6.º básico:\n• El mensaje dice: «Entregar antes del tercer turno».\n• No especifica si el tercer turno está incluido.\n• El responsable no está disponible por el momento.","question":"¿Qué interpretación es más responsable?","options":["Aclarar el plazo antes de comprometer la entrega","Suponer que cualquier hora sirve","Cambiar el mensaje original"],"correct":0,"explain":"Una instrucción ambigua exige aclaración, no una suposición oculta.","hint":"Localiza la parte que admite dos interpretaciones.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-039","grade":6,"level":4,"skill":"método científico","title":"Expediente 39: El experimento de las semillas","story":"Informe para 6.º básico:\n• Dos plantas recibieron distinta cantidad de agua.\n• También crecieron con distinta luz.\n• La planta más iluminada creció más.","question":"¿Qué impide atribuir la diferencia solo al agua?","options":["Las dos variables cambiaron","Las plantas tienen hojas","La luz no puede influir"],"correct":0,"explain":"Al variar luz y agua no se aísla una sola causa.","hint":"Identifica todas las condiciones que cambiaron.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N6-040","grade":6,"level":4,"skill":"evaluación de testimonios","title":"Expediente 40: El testigo distante","story":"Informe para 6.º básico:\n• Una persona oyó un golpe desde otro edificio.\n• No vio el lugar de origen.\n• Otro testigo observó una puerta cerrarse al mismo tiempo.","question":"¿Qué sabemos con mayor seguridad?","options":["Que alguien cometió un delito","Que hubo sonidos y una puerta cerrándose","Que ambos testigos vieron lo mismo"],"correct":1,"explain":"Los testimonios describen observaciones distintas, no una causa confirmada.","hint":"Separa lo oído de lo observado.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-001","grade":7,"level":1,"skill":"lógica deductiva","title":"Expediente 1: La crónica del monasterio","story":"• Un monje describe una hambruna de otra región veinte años después de ocurrida.","question":"¿Qué pregunta es crucial?","options":["¿Su letra era bonita?","¿Cuántas páginas tiene?","¿De dónde obtuvo sus datos?"],"correct":2,"explain":"La distancia temporal y geográfica exige contrastar fuentes.","hint":"Examina autoría y acceso a los hechos.","hint2":"Compara las evidencias y evita afirmar más de lo que permiten."},{"id":"N7-002","grade":7,"level":1,"skill":"contradicciones","title":"Expediente 2: La epidemia portuaria","story":"• Una ciudad con más barcos también tenía más habitantes. Registró más enfermos que otra ciudad.","question":"¿Qué conclusión es rigurosa?","options":["No puede aislarse una causa","Solo influyeron los barcos","La población no influye"],"correct":0,"explain":"Hay varias variables posibles.","hint":"Busca explicaciones alternativas.","hint2":"Compara las evidencias y evita afirmar más de lo que permiten."},{"id":"N7-003","grade":7,"level":1,"skill":"pensamiento crítico","title":"Expediente 3: El mapa dañado","story":"• La leyenda de un mapa medieval está incompleta y no identifica una ruta.","question":"¿Qué conviene hacer?","options":["Inventar el símbolo","Comparar con otros mapas de la época","Descartar todos los mapas"],"correct":1,"explain":"La corroboración puede aclarar el símbolo.","hint":"Contrasta fuentes.","hint2":"Compara las evidencias y evita afirmar más de lo que permiten."},{"id":"N7-004","grade":7,"level":1,"skill":"observación","title":"Expediente 4: Dos viajeros","story":"• Dos viajeros coinciden en la fecha de una feria, pero no en la cantidad de comerciantes.","question":"¿Qué está corroborado?","options":["La cantidad","Los precios","La fecha"],"correct":2,"explain":"Ambos coinciden en la fecha.","hint":"Identifica las coincidencias.","hint2":"Compara las evidencias y evita afirmar más de lo que permiten."},{"id":"N7-005","grade":7,"level":1,"skill":"causa y correlación","title":"Expediente 5: La cadena de rumores","story":"• Tres crónicas medievales repiten una historia, pero dos copian explícitamente a la primera.","question":"¿Qué riesgo existe?","options":["Son tres testimonios independientes","La repetición puede aparentar corroboración","Todas son falsas necesariamente"],"correct":1,"explain":"Las fuentes dependientes no corroboran de manera independiente.","hint":"Rastrea quién copió a quién.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N7-006","grade":7,"level":1,"skill":"planificación","title":"Expediente 6: El sello del archivo","story":"• Un pergamino tiene un sello similar al de una abadía, pero no se conoce su procedencia.","question":"¿Qué sería necesario para autenticarlo?","options":["Examinar procedencia y materiales","Elegirlo por apariencia","Atribuirlo sin pruebas"],"correct":0,"explain":"La autenticidad exige más que semejanza visual.","hint":"Piensa en cómo llegó el documento.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N7-007","grade":7,"level":1,"skill":"metacognición","title":"Expediente 7: La crisis de las cosechas","story":"• Una región sufre malas cosechas, epidemias y guerra en años próximos.","question":"¿Qué interpretación es más rigurosa?","options":["Solo influyó la guerra","No hubo relaciones","Pueden interactuar varios factores"],"correct":2,"explain":"Las crisis históricas pueden tener causas relacionadas.","hint":"Considera la multicausalidad.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N7-008","grade":7,"level":1,"skill":"cálculo aplicado","title":"Expediente 8: La ruta mercantil","story":"• Una ruta corta atraviesa una zona de conflicto. Otra es más larga, pero segura y abastecida.","question":"¿Qué decisión estratégica se sostiene mejor?","options":["Usar siempre la más corta","Comparar seguridad, costos y abastecimiento","Ignorar el conflicto"],"correct":1,"explain":"La distancia es solo una de varias restricciones.","hint":"Evalúa los riesgos.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N7-009","grade":7,"level":1,"skill":"inferencia","title":"Expediente 9: El cronista revisa","story":"• Un cronista descubre que confundió dos fechas y corrige su manuscrito dejando constancia del cambio.","question":"¿Qué principio aplica?","options":["Rectificación transparente","Ocultamiento","Certeza absoluta"],"correct":0,"explain":"La corrección documentada fortalece la trazabilidad histórica.","hint":"Considera qué hace con el error.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N7-010","grade":7,"level":1,"skill":"evaluación de fuentes","title":"Expediente 10: El tributo de las aldeas","story":"• Cuatro aldeas entregan 15 sacos cada una. El almacén ya contiene 10.","question":"¿Cuántos sacos habrá en total?","options":["60","65","70"],"correct":2,"explain":"Cuatro por quince más diez da setenta.","hint":"Multiplica y suma lo existente.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N7-011","grade":7,"level":2,"skill":"organización de datos","title":"Expediente 11: La lista duplicada","story":"Informe para 7.º básico:\n• El archivo contiene 12 nombres.\n• Dos nombres están repetidos exactamente.\n• El Consejo solicita contar personas distintas.","question":"¿Qué se debe hacer?","options":["Contar 12 personas sin revisar","Eliminar todos los nombres","Revisar duplicados antes de contar"],"correct":2,"explain":"Los registros duplicados pueden inflar el total de personas.","hint":"Distingue registros de individuos.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-012","grade":7,"level":2,"skill":"sesgos","title":"Expediente 12: La profecía flexible","story":"Informe para 7.º básico:\n• Un consejero anunció: «Habrá un cambio importante».\n• Después de cualquier suceso, afirma que lo predijo.\n• Nunca indicó fecha ni criterio para verificarlo.","question":"¿Qué problema tiene la afirmación?","options":["No permite una comprobación clara","Es una predicción numérica exacta","Queda demostrada por repetirse"],"correct":0,"explain":"Una predicción demasiado vaga puede acomodarse a casi cualquier resultado.","hint":"Pregunta cómo podría demostrarse que estaba equivocada.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-013","grade":7,"level":2,"skill":"estadística crítica","title":"Expediente 13: La muestra parcial","story":"Informe para 7.º básico:\n• Se entrevistó a diez personas de una sola sala.\n• Nueve apoyan una medida.\n• La ciudad tiene miles de habitantes.","question":"¿Qué conclusión es válida?","options":["Toda la ciudad apoya la medida","Nueve de las diez personas entrevistadas la apoyan","Nadie se opone"],"correct":1,"explain":"Una muestra limitada no representa automáticamente a toda la población.","hint":"Distingue la muestra de la población.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-014","grade":7,"level":2,"skill":"memoria de trabajo","title":"Expediente 14: El archivo de sonidos","story":"Informe para 7.º básico:\n• Secuencia registrada: campana, tambor, flauta, campana.\n• La tercera señal fue flauta.\n• El técnico debe reconstruir el orden.","question":"¿Qué instrumento sonó inmediatamente antes de la última campana?","options":["Tambor","Flauta","Campana"],"correct":1,"explain":"La tercera señal fue flauta y la cuarta, campana.","hint":"Enumera las señales en orden.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-015","grade":7,"level":2,"skill":"negociación","title":"Expediente 15: El pacto entre casas","story":"Informe para 7.º básico:\n• Dos casas necesitan agua.\n• La primera controla el depósito.\n• La segunda dispone de filtros necesarios para potabilizarla.","question":"¿Qué acuerdo atiende mejor los intereses de ambas?","options":["Compartir agua tratada mediante cooperación","Destruir los filtros","Negarse a conversar"],"correct":0,"explain":"Identificar necesidades complementarias facilita una solución cooperativa.","hint":"¿Qué aporta cada casa que necesita la otra?","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-016","grade":7,"level":2,"skill":"clasificación","title":"Expediente 16: La puerta de tres símbolos","story":"Informe para 7.º básico:\n• Las puertas seguras muestran estrella y triángulo.\n• Una puerta tiene estrella y triángulo.\n• Otra solo muestra estrella.","question":"¿Cuál cumple los dos criterios observados?","options":["Solo la primera puerta","Solo la segunda puerta","Ambas"],"correct":0,"explain":"La regla exige ambos símbolos, no solo uno.","hint":"Comprueba cada condición por separado.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-017","grade":7,"level":2,"skill":"historia y fuentes","title":"Expediente 17: La crónica contradictoria","story":"Informe para 7.º básico:\n• Una crónica oficial atribuye una victoria a un solo comandante.\n• Cartas de participantes describen acciones de varios grupos.\n• Los documentos fueron escritos desde perspectivas diferentes.","question":"¿Qué método ayuda a comprender el hecho?","options":["Comparar testimonios y sus perspectivas","Aceptar solo la versión oficial","Descartar todas las fuentes"],"correct":0,"explain":"Contrastar perspectivas reduce el riesgo de una interpretación unilateral.","hint":"Ninguna fuente se interpreta sin contexto.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-018","grade":7,"level":2,"skill":"causalidad","title":"Expediente 18: La alarma y el humo","story":"Informe para 7.º básico:\n• Se activó una alarma.\n• Poco después se observó humo.\n• No se ha identificado el origen del humo.","question":"¿Qué conclusión evita un error causal?","options":["La alarma produjo el humo","La alarma y el humo ocurrieron próximos, pero falta investigar su relación","El humo nunca existió"],"correct":1,"explain":"La sucesión temporal no prueba causalidad.","hint":"Ocurrir antes no siempre significa causar.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-019","grade":7,"level":2,"skill":"lenguaje","title":"Expediente 19: La traducción dudosa","story":"Informe para 7.º básico:\n• Un término antiguo puede significar «casa» o «familia».\n• La frase habla de proteger a sus integrantes.\n• No existe una traducción confirmada.","question":"¿Qué conviene hacer?","options":["Reconocer las dos posibilidades y buscar contexto","Elegir una traducción al azar como definitiva","Eliminar el término"],"correct":0,"explain":"La ambigüedad se resuelve con contexto y evidencia lingüística.","hint":"Busca pistas en las palabras cercanas.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-020","grade":7,"level":2,"skill":"observación científica","title":"Expediente 20: La sombra del reloj","story":"Informe para 7.º básico:\n• La sombra era larga temprano.\n• Al mediodía fue más corta.\n• La medición se hizo en el mismo lugar.","question":"¿Qué variable se relaciona con el cambio?","options":["La posición aparente del Sol","El nombre del observador","La tinta del registro"],"correct":0,"explain":"La longitud de la sombra depende del ángulo de iluminación.","hint":"Piensa qué cambia en el cielo durante el día.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-021","grade":7,"level":3,"skill":"lógica","title":"Expediente 21: El permiso perdido","story":"Informe para 7.º básico:\n• Toda persona autorizada tiene credencial vigente.\n• Una persona no tiene credencial vigente.\n• No hay excepciones registradas a la regla.","question":"¿Qué se deduce bajo esa regla?","options":["Esa persona no está autorizada","La persona tiene dos credenciales","La regla no se aplica"],"correct":0,"explain":"Si la credencial vigente es condición necesaria, su ausencia excluye autorización.","hint":"Una condición necesaria debe cumplirse.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-022","grade":7,"level":3,"skill":"verificación","title":"Expediente 22: El rumor del mercado","story":"Informe para 7.º básico:\n• Tres personas repiten la misma noticia.\n• Las tres la escucharon de un único mensaje anónimo.\n• No hay confirmación externa.","question":"¿Cuántas fuentes independientes hay?","options":["Tres","Una fuente original no verificada","Cuatro"],"correct":1,"explain":"Repetir una noticia no crea nuevas fuentes independientes.","hint":"Rastrea el origen de cada repetición.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-023","grade":7,"level":3,"skill":"razonamiento ético","title":"Expediente 23: La elección del Consejo","story":"Informe para 7.º básico:\n• Una norma se aplicó a un estudiante.\n• Otro estudiante en la misma situación recibió una excepción sin justificación.\n• El Consejo revisa la coherencia de sus decisiones.","question":"¿Qué principio debe examinarse?","options":["Aplicación equitativa de las normas","Preferencia personal del consejero","Cantidad de aplausos"],"correct":0,"explain":"Las decisiones equivalentes requieren criterios consistentes o razones explícitas.","hint":"Compara situaciones y justificaciones.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-024","grade":7,"level":3,"skill":"hipótesis científica","title":"Expediente 24: El mineral brillante","story":"Informe para 7.º básico:\n• Dos minerales tienen el mismo color.\n• Uno responde a un imán y el otro no.\n• Se desconoce su composición.","question":"¿Qué afirmación es correcta?","options":["Son necesariamente idénticos","El color por sí solo no determina que sean el mismo mineral","Ambos son magnéticos"],"correct":1,"explain":"Una propiedad compartida no basta para identificar materiales.","hint":"Busca una característica que los diferencie.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-025","grade":7,"level":3,"skill":"secuenciación","title":"Expediente 25: La contraseña fragmentada","story":"Informe para 7.º básico:\n• Primera instrucción: activar el panel.\n• Segunda: introducir la clave.\n• Tercera: confirmar el acceso.","question":"¿Qué debe hacerse inmediatamente después de activar el panel?","options":["Confirmar acceso","Introducir la clave","Cerrar el panel"],"correct":1,"explain":"La segunda acción sigue a la primera.","hint":"Revisa el orden explícito de las instrucciones.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-026","grade":7,"level":3,"skill":"investigación","title":"Expediente 26: La biblioteca extraviada","story":"Informe para 7.º básico:\n• El inventario indica que faltan tres libros.\n• Dos aparecen prestados con fecha de devolución futura.\n• Del tercero no existe registro de préstamo.","question":"¿Qué caso requiere investigación adicional?","options":["Los tres por igual","Solo los dos prestados","El libro sin registro de préstamo"],"correct":2,"explain":"Los préstamos documentados explican dos ausencias; la tercera sigue sin explicación.","hint":"Separa ausencias justificadas de las no justificadas.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-027","grade":7,"level":3,"skill":"análisis documental","title":"Expediente 27: La bitácora alterada","story":"Informe para 7.º básico:\n• La bitácora registra una salida a las 08:15.\n• El reloj de la torre se detuvo a las 08:00.\n• El registro fue escrito a mano después del incidente.","question":"¿Qué conviene verificar primero?","options":["La hora usando un reloj independiente","La caligrafía del guardia demuestra culpa","La salida nunca ocurrió"],"correct":0,"explain":"La hora escrita puede ser inexacta si el reloj local estaba detenido.","hint":"Compara el reloj con una fuente independiente.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-028","grade":7,"level":3,"skill":"observación","title":"Expediente 28: La sala silenciosa","story":"Informe para 7.º básico:\n• La puerta está cerrada por dentro.\n• Hay una ventana abierta.\n• El polvo del alféizar presenta una marca reciente.","question":"¿Qué afirmación es prudente?","options":["La ventana pudo haber sido utilizada","La persona salió necesariamente por la ventana","La habitación estuvo siempre vacía"],"correct":0,"explain":"La marca sugiere actividad, pero no determina quién ni cómo.","hint":"No confundas indicio con certeza.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-029","grade":7,"level":3,"skill":"pensamiento espacial","title":"Expediente 29: El mapa incompleto","story":"Informe para 7.º básico:\n• El mapa marca un puente al norte.\n• El informe de terreno indica que ese puente está cortado.\n• Existe un sendero alternativo sin inspeccionar.","question":"¿Cuál es la mejor decisión?","options":["Usar el puente porque figura en el mapa","Inspeccionar el sendero antes de elegir ruta","Afirmar que no hay caminos"],"correct":1,"explain":"Un mapa desactualizado no reemplaza la verificación del terreno.","hint":"Contrasta mapa e informe reciente.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-030","grade":7,"level":3,"skill":"probabilidad","title":"Expediente 30: La predicción del oráculo","story":"Informe para 7.º básico:\n• Un pronóstico anticipó lluvia en siete de diez días similares.\n• Hoy presenta condiciones semejantes.\n• El pronóstico no garantiza el resultado.","question":"¿Cómo interpretar el pronóstico?","options":["Lloverá con absoluta seguridad","Es imposible que llueva","La lluvia es probable, pero no segura"],"correct":2,"explain":"Una frecuencia alta no equivale a certeza.","hint":"Distingue probabilidad de seguridad.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-031","grade":7,"level":4,"skill":"comprensión","title":"Expediente 31: La orden ambigua","story":"Informe para 7.º básico:\n• El mensaje dice: «Entregar antes del tercer turno».\n• No especifica si el tercer turno está incluido.\n• El responsable no está disponible por el momento.","question":"¿Qué interpretación es más responsable?","options":["Aclarar el plazo antes de comprometer la entrega","Suponer que cualquier hora sirve","Cambiar el mensaje original"],"correct":0,"explain":"Una instrucción ambigua exige aclaración, no una suposición oculta.","hint":"Localiza la parte que admite dos interpretaciones.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-032","grade":7,"level":4,"skill":"método científico","title":"Expediente 32: El experimento de las semillas","story":"Informe para 7.º básico:\n• Dos plantas recibieron distinta cantidad de agua.\n• También crecieron con distinta luz.\n• La planta más iluminada creció más.","question":"¿Qué impide atribuir la diferencia solo al agua?","options":["Las dos variables cambiaron","Las plantas tienen hojas","La luz no puede influir"],"correct":0,"explain":"Al variar luz y agua no se aísla una sola causa.","hint":"Identifica todas las condiciones que cambiaron.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-033","grade":7,"level":4,"skill":"evaluación de testimonios","title":"Expediente 33: El testigo distante","story":"Informe para 7.º básico:\n• Una persona oyó un golpe desde otro edificio.\n• No vio el lugar de origen.\n• Otro testigo observó una puerta cerrarse al mismo tiempo.","question":"¿Qué sabemos con mayor seguridad?","options":["Que alguien cometió un delito","Que hubo sonidos y una puerta cerrándose","Que ambos testigos vieron lo mismo"],"correct":1,"explain":"Los testimonios describen observaciones distintas, no una causa confirmada.","hint":"Separa lo oído de lo observado.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-034","grade":7,"level":4,"skill":"patrones no numéricos","title":"Expediente 34: Las tres señales","story":"Informe para 7.º básico:\n• Cada aviso de emergencia comienza con círculo rojo.\n• Dos mensajes auténticos muestran círculo rojo y sello azul.\n• Un tercer mensaje tiene círculo verde y no incluye sello.","question":"¿Qué procede hacer?","options":["Tratar el tercer mensaje como no verificado","Declarar que el tercero es auténtico","Ignorar todos los mensajes"],"correct":0,"explain":"La falta de rasgos de autenticidad exige comprobación.","hint":"Compara señales comunes de los avisos verificados.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-035","grade":7,"level":4,"skill":"ética y decisión","title":"Expediente 35: El recurso compartido","story":"Informe para 7.º básico:\n• Hay un equipo médico para dos grupos.\n• El grupo A presenta una urgencia documentada.\n• El grupo B tiene una necesidad menor que puede esperar.","question":"¿Qué criterio es más defendible?","options":["Atender primero la urgencia documentada","Favorecer al grupo más numeroso sin evaluar gravedad","Decidir por amistad"],"correct":0,"explain":"La prioridad se fundamenta en necesidad y gravedad, no favoritismo.","hint":"Diferencia urgencia de preferencia.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-036","grade":7,"level":4,"skill":"contexto histórico","title":"Expediente 36: La carta sin fecha","story":"Informe para 7.º básico:\n• Una carta menciona una sequía.\n• No tiene fecha ni autor identificado.\n• Un registro regional confirma sequías en varios años distintos.","question":"¿Qué dato falta para situarla históricamente?","options":["El color de la tinta","Una fecha o referencia temporal verificable","El número de palabras"],"correct":1,"explain":"Sin referencia temporal no se puede asociar con seguridad a un año.","hint":"Busca qué permite ubicar un documento en el tiempo.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-037","grade":7,"level":4,"skill":"fiabilidad","title":"Expediente 37: El sensor defectuoso","story":"Informe para 7.º básico:\n• Dos sensores marcan 18 grados.\n• Un tercero indica 45 grados.\n• El tercer sensor no ha sido calibrado recientemente.","question":"¿Qué acción mejora la fiabilidad?","options":["Usar únicamente la lectura extrema","Revisar la calibración y contrastar mediciones","Promediar sin examinar errores"],"correct":1,"explain":"Una lectura atípica exige comprobar el instrumento.","hint":"¿Qué diferencia hay entre los sensores?","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-038","grade":7,"level":4,"skill":"deducción","title":"Expediente 38: El idioma desconocido","story":"Informe para 7.º básico:\n• La palabra «tal» aparece en todos los saludos.\n• Nunca aparece en mensajes de despedida del archivo.\n• El corpus contiene solo seis mensajes.","question":"¿Qué hipótesis es razonable?","options":["«tal» podría relacionarse con saludar","«tal» significa necesariamente emperador","Ya conocemos todo el idioma"],"correct":0,"explain":"La coincidencia sugiere una función, pero la muestra es pequeña.","hint":"Observa el contexto de aparición de la palabra.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-039","grade":7,"level":4,"skill":"alfabetización mediática","title":"Expediente 39: El retrato recortado","story":"Informe para 7.º básico:\n• Una imagen muestra a un guardia corriendo.\n• La fotografía completa revela que corre hacia una persona caída.\n• El titular recortado dice: «Guardia huye».","question":"¿Qué demuestra el caso?","options":["Que el recorte puede alterar la interpretación","Que todas las fotos son falsas","Que el guardia cometió una falta"],"correct":0,"explain":"Omitir contexto visual puede cambiar el significado atribuido.","hint":"Compara el recorte con la imagen completa.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N7-040","grade":7,"level":4,"skill":"planificación","title":"Expediente 40: La ruta de los mensajeros","story":"Informe para 7.º básico:\n• Ruta A es corta, pero atraviesa una zona cerrada.\n• Ruta B es más larga y está confirmada como transitable.\n• El mensaje debe llegar sin poner en riesgo al equipo.","question":"¿Qué ruta conviene elegir?","options":["Ruta A por ser más corta","Ruta B por ser transitable","Ninguna porque ambas tienen distancia"],"correct":1,"explain":"La seguridad y viabilidad importan más que la distancia mínima.","hint":"Una ruta corta no sirve si está cerrada.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-001","grade":8,"level":1,"skill":"contradicciones","title":"Expediente 1: El panfleto revolucionario","story":"• Un panfleto de 1789 denuncia privilegios y fue escrito por un partidario de la revolución.","question":"¿Cómo debe leerse?","options":["Como texto neutral","Como fuente primaria con perspectiva","Como documento inútil"],"correct":1,"explain":"Una fuente puede ser primaria y tener una perspectiva.","hint":"Distingue valor y sesgo.","hint2":"Compara las evidencias y evita afirmar más de lo que permiten."},{"id":"N8-002","grade":8,"level":1,"skill":"pensamiento crítico","title":"Expediente 2: La densidad regional","story":"• Dos regiones tienen cien mil habitantes. Una ocupa mil kilómetros cuadrados y otra cinco mil.","question":"¿Cuál es más densa?","options":["Tienen igual densidad","La segunda","La primera"],"correct":2,"explain":"Con igual población, menor superficie implica mayor densidad.","hint":"Divide población por superficie.","hint2":"Compara las evidencias y evita afirmar más de lo que permiten."},{"id":"N8-003","grade":8,"level":1,"skill":"observación","title":"Expediente 3: El gráfico recortado","story":"• Un gráfico empieza su eje vertical en 95 y presenta valores entre 96 y 100.","question":"¿Qué riesgo presenta?","options":["Exagerar diferencias pequeñas","Ocultar todos los valores","Demostrar una crisis"],"correct":0,"explain":"El eje truncado amplifica visualmente variaciones pequeñas.","hint":"Observa dónde empieza el eje.","hint2":"Compara las evidencias y evita afirmar más de lo que permiten."},{"id":"N8-004","grade":8,"level":1,"skill":"causa y correlación","title":"Expediente 4: La migración y la industria","story":"• Una comuna recibe habitantes y abre una industria al mismo tiempo, sin datos sobre motivos de llegada.","question":"¿Qué conclusión es excesiva?","options":["La población aumentó","Todos llegaron por la industria","Coincidieron dos hechos"],"correct":1,"explain":"La simultaneidad no prueba una causa exclusiva.","hint":"Distingue coincidencia y causalidad.","hint2":"Compara las evidencias y evita afirmar más de lo que permiten."},{"id":"N8-005","grade":8,"level":1,"skill":"planificación","title":"Expediente 5: El video recortado","story":"• Un video viral muestra diez segundos de una discusión pública, sin el contexto anterior.","question":"¿Qué conclusión es más responsable?","options":["Conocer toda la discusión","Examinar la grabación completa","Ignorar todas las pruebas"],"correct":1,"explain":"Un fragmento no permite reconstruir toda la secuencia.","hint":"Identifica qué parte falta.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N8-006","grade":8,"level":1,"skill":"metacognición","title":"Expediente 6: El archivo de la reforma","story":"• Un documento político aparece sin firma ni fecha. Se atribuye a una autoridad, pero no hay registro de procedencia.","question":"¿Qué verificación es prioritaria?","options":["Autenticidad y cadena de custodia","Popularidad en redes","Número de páginas"],"correct":0,"explain":"La atribución exige procedencia verificable.","hint":"Pregunta de dónde salió el documento.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N8-007","grade":8,"level":1,"skill":"cálculo aplicado","title":"Expediente 7: La expansión urbana","story":"• Una ciudad crece mientras se construye una nueva carretera y aumenta el empleo.","question":"¿Qué inferencia es rigurosa?","options":["Solo la carretera explica el crecimiento","El empleo nunca influye","Pueden existir causas múltiples"],"correct":2,"explain":"La simultaneidad no identifica una causa única.","hint":"Considera distintos factores.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N8-008","grade":8,"level":1,"skill":"inferencia","title":"Expediente 8: El presupuesto regional","story":"• Un proyecto cuesta menos, pero beneficia a menos localidades y aumenta el riesgo ambiental.","question":"¿Cómo evaluar alternativas?","options":["Elegir solo el menor costo","Comparar costo, cobertura e impacto","Ignorar los efectos ambientales"],"correct":1,"explain":"La evaluación debe considerar varias dimensiones.","hint":"Piensa en consecuencias y beneficiarios.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N8-009","grade":8,"level":1,"skill":"evaluación de fuentes","title":"Expediente 9: La hipótesis corregida","story":"• Un análisis atribuyó una variación demográfica a la migración; nuevos datos muestran cambios en nacimientos y defunciones.","question":"¿Qué corresponde?","options":["Revisar el modelo explicativo","Mantener la conclusión inicial","Descartar los datos nuevos"],"correct":0,"explain":"El crecimiento poblacional puede responder a varios componentes.","hint":"Incluye toda la evidencia disponible.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N8-010","grade":8,"level":1,"skill":"lógica deductiva","title":"Expediente 10: El presupuesto de transporte","story":"• Un plan dispone de 180 unidades. Cada recorrido cuesta 45.","question":"¿Cuántos recorridos completos se financian?","options":["Tres","Cinco","Cuatro"],"correct":2,"explain":"180 dividido por 45 es 4.","hint":"Divide presupuesto por costo unitario.","hint2":"Contrasta las opciones con los datos del expediente antes de concluir."},{"id":"N8-011","grade":8,"level":2,"skill":"causalidad","title":"Expediente 11: La alarma y el humo","story":"Informe para 8.º básico:\n• Se activó una alarma.\n• Poco después se observó humo.\n• No se ha identificado el origen del humo.","question":"¿Qué conclusión evita un error causal?","options":["La alarma produjo el humo","La alarma y el humo ocurrieron próximos, pero falta investigar su relación","El humo nunca existió"],"correct":1,"explain":"La sucesión temporal no prueba causalidad.","hint":"Ocurrir antes no siempre significa causar.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-012","grade":8,"level":2,"skill":"lenguaje","title":"Expediente 12: La traducción dudosa","story":"Informe para 8.º básico:\n• Un término antiguo puede significar «casa» o «familia».\n• La frase habla de proteger a sus integrantes.\n• No existe una traducción confirmada.","question":"¿Qué conviene hacer?","options":["Reconocer las dos posibilidades y buscar contexto","Elegir una traducción al azar como definitiva","Eliminar el término"],"correct":0,"explain":"La ambigüedad se resuelve con contexto y evidencia lingüística.","hint":"Busca pistas en las palabras cercanas.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-013","grade":8,"level":2,"skill":"observación científica","title":"Expediente 13: La sombra del reloj","story":"Informe para 8.º básico:\n• La sombra era larga temprano.\n• Al mediodía fue más corta.\n• La medición se hizo en el mismo lugar.","question":"¿Qué variable se relaciona con el cambio?","options":["La posición aparente del Sol","El nombre del observador","La tinta del registro"],"correct":0,"explain":"La longitud de la sombra depende del ángulo de iluminación.","hint":"Piensa qué cambia en el cielo durante el día.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-014","grade":8,"level":2,"skill":"lógica","title":"Expediente 14: El permiso perdido","story":"Informe para 8.º básico:\n• Toda persona autorizada tiene credencial vigente.\n• Una persona no tiene credencial vigente.\n• No hay excepciones registradas a la regla.","question":"¿Qué se deduce bajo esa regla?","options":["Esa persona no está autorizada","La persona tiene dos credenciales","La regla no se aplica"],"correct":0,"explain":"Si la credencial vigente es condición necesaria, su ausencia excluye autorización.","hint":"Una condición necesaria debe cumplirse.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-015","grade":8,"level":2,"skill":"verificación","title":"Expediente 15: El rumor del mercado","story":"Informe para 8.º básico:\n• Tres personas repiten la misma noticia.\n• Las tres la escucharon de un único mensaje anónimo.\n• No hay confirmación externa.","question":"¿Cuántas fuentes independientes hay?","options":["Tres","Una fuente original no verificada","Cuatro"],"correct":1,"explain":"Repetir una noticia no crea nuevas fuentes independientes.","hint":"Rastrea el origen de cada repetición.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-016","grade":8,"level":2,"skill":"razonamiento ético","title":"Expediente 16: La elección del Consejo","story":"Informe para 8.º básico:\n• Una norma se aplicó a un estudiante.\n• Otro estudiante en la misma situación recibió una excepción sin justificación.\n• El Consejo revisa la coherencia de sus decisiones.","question":"¿Qué principio debe examinarse?","options":["Aplicación equitativa de las normas","Preferencia personal del consejero","Cantidad de aplausos"],"correct":0,"explain":"Las decisiones equivalentes requieren criterios consistentes o razones explícitas.","hint":"Compara situaciones y justificaciones.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-017","grade":8,"level":2,"skill":"hipótesis científica","title":"Expediente 17: El mineral brillante","story":"Informe para 8.º básico:\n• Dos minerales tienen el mismo color.\n• Uno responde a un imán y el otro no.\n• Se desconoce su composición.","question":"¿Qué afirmación es correcta?","options":["Son necesariamente idénticos","El color por sí solo no determina que sean el mismo mineral","Ambos son magnéticos"],"correct":1,"explain":"Una propiedad compartida no basta para identificar materiales.","hint":"Busca una característica que los diferencie.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-018","grade":8,"level":2,"skill":"secuenciación","title":"Expediente 18: La contraseña fragmentada","story":"Informe para 8.º básico:\n• Primera instrucción: activar el panel.\n• Segunda: introducir la clave.\n• Tercera: confirmar el acceso.","question":"¿Qué debe hacerse inmediatamente después de activar el panel?","options":["Confirmar acceso","Introducir la clave","Cerrar el panel"],"correct":1,"explain":"La segunda acción sigue a la primera.","hint":"Revisa el orden explícito de las instrucciones.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-019","grade":8,"level":2,"skill":"investigación","title":"Expediente 19: La biblioteca extraviada","story":"Informe para 8.º básico:\n• El inventario indica que faltan tres libros.\n• Dos aparecen prestados con fecha de devolución futura.\n• Del tercero no existe registro de préstamo.","question":"¿Qué caso requiere investigación adicional?","options":["Los tres por igual","Solo los dos prestados","El libro sin registro de préstamo"],"correct":2,"explain":"Los préstamos documentados explican dos ausencias; la tercera sigue sin explicación.","hint":"Separa ausencias justificadas de las no justificadas.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-020","grade":8,"level":2,"skill":"análisis documental","title":"Expediente 20: La bitácora alterada","story":"Informe para 8.º básico:\n• La bitácora registra una salida a las 08:15.\n• El reloj de la torre se detuvo a las 08:00.\n• El registro fue escrito a mano después del incidente.","question":"¿Qué conviene verificar primero?","options":["La hora usando un reloj independiente","La caligrafía del guardia demuestra culpa","La salida nunca ocurrió"],"correct":0,"explain":"La hora escrita puede ser inexacta si el reloj local estaba detenido.","hint":"Compara el reloj con una fuente independiente.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-021","grade":8,"level":3,"skill":"observación","title":"Expediente 21: La sala silenciosa","story":"Informe para 8.º básico:\n• La puerta está cerrada por dentro.\n• Hay una ventana abierta.\n• El polvo del alféizar presenta una marca reciente.","question":"¿Qué afirmación es prudente?","options":["La ventana pudo haber sido utilizada","La persona salió necesariamente por la ventana","La habitación estuvo siempre vacía"],"correct":0,"explain":"La marca sugiere actividad, pero no determina quién ni cómo.","hint":"No confundas indicio con certeza.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-022","grade":8,"level":3,"skill":"pensamiento espacial","title":"Expediente 22: El mapa incompleto","story":"Informe para 8.º básico:\n• El mapa marca un puente al norte.\n• El informe de terreno indica que ese puente está cortado.\n• Existe un sendero alternativo sin inspeccionar.","question":"¿Cuál es la mejor decisión?","options":["Usar el puente porque figura en el mapa","Inspeccionar el sendero antes de elegir ruta","Afirmar que no hay caminos"],"correct":1,"explain":"Un mapa desactualizado no reemplaza la verificación del terreno.","hint":"Contrasta mapa e informe reciente.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-023","grade":8,"level":3,"skill":"probabilidad","title":"Expediente 23: La predicción del oráculo","story":"Informe para 8.º básico:\n• Un pronóstico anticipó lluvia en siete de diez días similares.\n• Hoy presenta condiciones semejantes.\n• El pronóstico no garantiza el resultado.","question":"¿Cómo interpretar el pronóstico?","options":["Lloverá con absoluta seguridad","Es imposible que llueva","La lluvia es probable, pero no segura"],"correct":2,"explain":"Una frecuencia alta no equivale a certeza.","hint":"Distingue probabilidad de seguridad.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-024","grade":8,"level":3,"skill":"comprensión","title":"Expediente 24: La orden ambigua","story":"Informe para 8.º básico:\n• El mensaje dice: «Entregar antes del tercer turno».\n• No especifica si el tercer turno está incluido.\n• El responsable no está disponible por el momento.","question":"¿Qué interpretación es más responsable?","options":["Aclarar el plazo antes de comprometer la entrega","Suponer que cualquier hora sirve","Cambiar el mensaje original"],"correct":0,"explain":"Una instrucción ambigua exige aclaración, no una suposición oculta.","hint":"Localiza la parte que admite dos interpretaciones.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-025","grade":8,"level":3,"skill":"método científico","title":"Expediente 25: El experimento de las semillas","story":"Informe para 8.º básico:\n• Dos plantas recibieron distinta cantidad de agua.\n• También crecieron con distinta luz.\n• La planta más iluminada creció más.","question":"¿Qué impide atribuir la diferencia solo al agua?","options":["Las dos variables cambiaron","Las plantas tienen hojas","La luz no puede influir"],"correct":0,"explain":"Al variar luz y agua no se aísla una sola causa.","hint":"Identifica todas las condiciones que cambiaron.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-026","grade":8,"level":3,"skill":"evaluación de testimonios","title":"Expediente 26: El testigo distante","story":"Informe para 8.º básico:\n• Una persona oyó un golpe desde otro edificio.\n• No vio el lugar de origen.\n• Otro testigo observó una puerta cerrarse al mismo tiempo.","question":"¿Qué sabemos con mayor seguridad?","options":["Que alguien cometió un delito","Que hubo sonidos y una puerta cerrándose","Que ambos testigos vieron lo mismo"],"correct":1,"explain":"Los testimonios describen observaciones distintas, no una causa confirmada.","hint":"Separa lo oído de lo observado.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-027","grade":8,"level":3,"skill":"patrones no numéricos","title":"Expediente 27: Las tres señales","story":"Informe para 8.º básico:\n• Cada aviso de emergencia comienza con círculo rojo.\n• Dos mensajes auténticos muestran círculo rojo y sello azul.\n• Un tercer mensaje tiene círculo verde y no incluye sello.","question":"¿Qué procede hacer?","options":["Tratar el tercer mensaje como no verificado","Declarar que el tercero es auténtico","Ignorar todos los mensajes"],"correct":0,"explain":"La falta de rasgos de autenticidad exige comprobación.","hint":"Compara señales comunes de los avisos verificados.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-028","grade":8,"level":3,"skill":"ética y decisión","title":"Expediente 28: El recurso compartido","story":"Informe para 8.º básico:\n• Hay un equipo médico para dos grupos.\n• El grupo A presenta una urgencia documentada.\n• El grupo B tiene una necesidad menor que puede esperar.","question":"¿Qué criterio es más defendible?","options":["Atender primero la urgencia documentada","Favorecer al grupo más numeroso sin evaluar gravedad","Decidir por amistad"],"correct":0,"explain":"La prioridad se fundamenta en necesidad y gravedad, no favoritismo.","hint":"Diferencia urgencia de preferencia.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-029","grade":8,"level":3,"skill":"contexto histórico","title":"Expediente 29: La carta sin fecha","story":"Informe para 8.º básico:\n• Una carta menciona una sequía.\n• No tiene fecha ni autor identificado.\n• Un registro regional confirma sequías en varios años distintos.","question":"¿Qué dato falta para situarla históricamente?","options":["El color de la tinta","Una fecha o referencia temporal verificable","El número de palabras"],"correct":1,"explain":"Sin referencia temporal no se puede asociar con seguridad a un año.","hint":"Busca qué permite ubicar un documento en el tiempo.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-030","grade":8,"level":3,"skill":"fiabilidad","title":"Expediente 30: El sensor defectuoso","story":"Informe para 8.º básico:\n• Dos sensores marcan 18 grados.\n• Un tercero indica 45 grados.\n• El tercer sensor no ha sido calibrado recientemente.","question":"¿Qué acción mejora la fiabilidad?","options":["Usar únicamente la lectura extrema","Revisar la calibración y contrastar mediciones","Promediar sin examinar errores"],"correct":1,"explain":"Una lectura atípica exige comprobar el instrumento.","hint":"¿Qué diferencia hay entre los sensores?","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-031","grade":8,"level":4,"skill":"deducción","title":"Expediente 31: El idioma desconocido","story":"Informe para 8.º básico:\n• La palabra «tal» aparece en todos los saludos.\n• Nunca aparece en mensajes de despedida del archivo.\n• El corpus contiene solo seis mensajes.","question":"¿Qué hipótesis es razonable?","options":["«tal» podría relacionarse con saludar","«tal» significa necesariamente emperador","Ya conocemos todo el idioma"],"correct":0,"explain":"La coincidencia sugiere una función, pero la muestra es pequeña.","hint":"Observa el contexto de aparición de la palabra.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-032","grade":8,"level":4,"skill":"alfabetización mediática","title":"Expediente 32: El retrato recortado","story":"Informe para 8.º básico:\n• Una imagen muestra a un guardia corriendo.\n• La fotografía completa revela que corre hacia una persona caída.\n• El titular recortado dice: «Guardia huye».","question":"¿Qué demuestra el caso?","options":["Que el recorte puede alterar la interpretación","Que todas las fotos son falsas","Que el guardia cometió una falta"],"correct":0,"explain":"Omitir contexto visual puede cambiar el significado atribuido.","hint":"Compara el recorte con la imagen completa.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-033","grade":8,"level":4,"skill":"planificación","title":"Expediente 33: La ruta de los mensajeros","story":"Informe para 8.º básico:\n• Ruta A es corta, pero atraviesa una zona cerrada.\n• Ruta B es más larga y está confirmada como transitable.\n• El mensaje debe llegar sin poner en riesgo al equipo.","question":"¿Qué ruta conviene elegir?","options":["Ruta A por ser más corta","Ruta B por ser transitable","Ninguna porque ambas tienen distancia"],"correct":1,"explain":"La seguridad y viabilidad importan más que la distancia mínima.","hint":"Una ruta corta no sirve si está cerrada.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-034","grade":8,"level":4,"skill":"organización de datos","title":"Expediente 34: La lista duplicada","story":"Informe para 8.º básico:\n• El archivo contiene 12 nombres.\n• Dos nombres están repetidos exactamente.\n• El Consejo solicita contar personas distintas.","question":"¿Qué se debe hacer?","options":["Contar 12 personas sin revisar","Eliminar todos los nombres","Revisar duplicados antes de contar"],"correct":2,"explain":"Los registros duplicados pueden inflar el total de personas.","hint":"Distingue registros de individuos.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-035","grade":8,"level":4,"skill":"sesgos","title":"Expediente 35: La profecía flexible","story":"Informe para 8.º básico:\n• Un consejero anunció: «Habrá un cambio importante».\n• Después de cualquier suceso, afirma que lo predijo.\n• Nunca indicó fecha ni criterio para verificarlo.","question":"¿Qué problema tiene la afirmación?","options":["No permite una comprobación clara","Es una predicción numérica exacta","Queda demostrada por repetirse"],"correct":0,"explain":"Una predicción demasiado vaga puede acomodarse a casi cualquier resultado.","hint":"Pregunta cómo podría demostrarse que estaba equivocada.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-036","grade":8,"level":4,"skill":"estadística crítica","title":"Expediente 36: La muestra parcial","story":"Informe para 8.º básico:\n• Se entrevistó a diez personas de una sola sala.\n• Nueve apoyan una medida.\n• La ciudad tiene miles de habitantes.","question":"¿Qué conclusión es válida?","options":["Toda la ciudad apoya la medida","Nueve de las diez personas entrevistadas la apoyan","Nadie se opone"],"correct":1,"explain":"Una muestra limitada no representa automáticamente a toda la población.","hint":"Distingue la muestra de la población.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-037","grade":8,"level":4,"skill":"memoria de trabajo","title":"Expediente 37: El archivo de sonidos","story":"Informe para 8.º básico:\n• Secuencia registrada: campana, tambor, flauta, campana.\n• La tercera señal fue flauta.\n• El técnico debe reconstruir el orden.","question":"¿Qué instrumento sonó inmediatamente antes de la última campana?","options":["Tambor","Flauta","Campana"],"correct":1,"explain":"La tercera señal fue flauta y la cuarta, campana.","hint":"Enumera las señales en orden.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-038","grade":8,"level":4,"skill":"negociación","title":"Expediente 38: El pacto entre casas","story":"Informe para 8.º básico:\n• Dos casas necesitan agua.\n• La primera controla el depósito.\n• La segunda dispone de filtros necesarios para potabilizarla.","question":"¿Qué acuerdo atiende mejor los intereses de ambas?","options":["Compartir agua tratada mediante cooperación","Destruir los filtros","Negarse a conversar"],"correct":0,"explain":"Identificar necesidades complementarias facilita una solución cooperativa.","hint":"¿Qué aporta cada casa que necesita la otra?","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-039","grade":8,"level":4,"skill":"clasificación","title":"Expediente 39: La puerta de tres símbolos","story":"Informe para 8.º básico:\n• Las puertas seguras muestran estrella y triángulo.\n• Una puerta tiene estrella y triángulo.\n• Otra solo muestra estrella.","question":"¿Cuál cumple los dos criterios observados?","options":["Solo la primera puerta","Solo la segunda puerta","Ambas"],"correct":0,"explain":"La regla exige ambos símbolos, no solo uno.","hint":"Comprueba cada condición por separado.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."},{"id":"N8-040","grade":8,"level":4,"skill":"historia y fuentes","title":"Expediente 40: La crónica contradictoria","story":"Informe para 8.º básico:\n• Una crónica oficial atribuye una victoria a un solo comandante.\n• Cartas de participantes describen acciones de varios grupos.\n• Los documentos fueron escritos desde perspectivas diferentes.","question":"¿Qué método ayuda a comprender el hecho?","options":["Comparar testimonios y sus perspectivas","Aceptar solo la versión oficial","Descartar todas las fuentes"],"correct":0,"explain":"Contrastar perspectivas reduce el riesgo de una interpretación unilateral.","hint":"Ninguna fuente se interpreta sin contexto.","hint2":"Revisa las evidencias una a una y descarta la conclusión que afirma más de lo que se puede demostrar."}];
